  'editor.pers.animSinPiezas': 'To create pose animations, build the body with 3D pieces in the Body tab.',

  // Descripciones de cuartos (listado "Agregar cuarto")
  'room.cocina.desc': 'Nutrition: log meals, macros, water and your weekly plan.',
  'room.ejercicio.desc': 'Strength, endurance and flexibility routines with goals.',
  'room.recamara.desc': 'Track your rest and write your personal anecdote book.',
  'room.descanso.desc': 'Your sleep as a night sky: schedule, alarm, score and night log.',
  'room.anecdotario.desc': 'Your personal journal: memories with photos and daily mood.',
  'room.despacho.desc': 'Finance: budget with expenses and income (fixed and variable), goals (financial calculators, savings/investing, debt) with simulators, and live markets.',
  'room.biblioteca.desc': 'Conversational encyclopedia: AI chats, wiki entries and study sessions.',
  'room.entretenimiento.desc': 'Archive of movies, series, books and board games.',
  'room.sala.desc': 'Plan trips: itinerary, expenses, checklist and wishlist.',
  'room.jardin.desc': 'Calm: guided meditations, breathing and gratitude journal.',
  'room.garage.desc': 'Maintenance of your vehicles and their services.',
  'room.diario.desc': 'Daily news hub, by category.',
  'room.hobbies.desc': 'Your pastimes and creative projects.',
  'room.idiomas.desc': 'Learn languages: AI tutor, spaced-repetition vocabulary, level syllabus and exercises.',
  'room.calendario.desc': 'Your calendar: events and routines by day, week and month.',
  'room.caminos.desc': 'Lay out race tracks, train rails and roller coasters on the map.',
  'room.canchas.desc': 'Place soccer, tennis, basketball and baseball courts on the map.',
  'room.huerto.desc': 'Prepare plots, sow crops, water them and harvest in real time.',
  'room.granja.desc': 'Raise hens, pigs, goats, sheep, cows and horses, and grow their food in the same editor.',
  'room.ideas.desc': 'Your idea journal and brainstorms, ten concept-map formats on a free canvas (mind map, tree, timeline, cycle, pyramid, Venn…) and eight diagrams to decide with (pros and cons, force field, SWOT, Eisenhower, decision tree, tier list, weighted decision matrix and Ishikawa), by hand or with AI.',
  'room.metas.desc':
    'What you set out to do, from the whole house: the list of goals with their sub-goals and steps, the plans the AI suggests for each one (phases with a date that turn into real sub-goals) and the timeline where everything takes up its period on the axis of time.',

  'room.computo.desc':
    'Computing room: a scientific calculator with your formula book hanging off it (Mathematics, Physics and Chemistry included and editable) and eight modes — a plotter with four types (2D, polar, parametric and 3D surface), binary and hexadecimal, matrices, systems of equations, unit conversion, tip and rule of three; and spreadsheets that export to Excel and PDF.',

