  'chat.manual.abrir': 'Manual: what you can ask for',
  'chat.manual.aviso.caminos': 'Build commands open a full-screen editor: the chat closes until you exit with ✕. Care actions work without leaving the chat.',
  'chat.manual.aviso.granja': 'Build commands open a full-screen editor: the chat closes until you exit with ✕. Care actions work without leaving the chat.',
