  'mascota.buho.nombre': 'Owl',
  'mascota.robot.nombre': 'Robot',
  'mascota.mago.saludo': 'I\'m your arcane architect. Tell me what you did and I shall inscribe it ✨',
  'mascota.gato.saludo': 'Meow. Tell me your stuff and I\'ll see where it goes 🐾',
  'mascota.perro.saludo': 'Woof! Tell me what you did and I\'ll save it right away! 🦴',
  'mascota.buho.saludo': 'Wise and attentive. Recount your day and I shall organize it.',
